'use client'

import { useCanvasLoop } from './canvas-loop'

// Turns text into target points by drawing it off screen and reading the pixels.
export function sampleText(text, w, h, step) {
  const c = document.createElement('canvas')
  c.width = Math.max(1, Math.floor(w)); c.height = Math.max(1, Math.floor(h))
  const x = c.getContext('2d', { willReadFrequently: true })
  if (!x) return []
  let size = Math.min(h * 0.5, 200)
  x.font = `700 ${size}px "Geist Variable", system-ui, sans-serif`
  const tw = x.measureText(text).width || 1
  size = Math.max(12, Math.min(size, (size * w * 0.86) / tw))
  x.font = `700 ${size}px "Geist Variable", system-ui, sans-serif`
  x.textAlign = 'center'; x.textBaseline = 'middle'; x.fillStyle = '#fff'
  x.fillText(text, c.width / 2, c.height / 2)
  let data
  try { data = x.getImageData(0, 0, c.width, c.height).data } catch { return [] }
  const out = []
  for (let y = 0; y < c.height; y += step) for (let xx = 0; xx < c.width; xx += step) if (data[(y * c.width + xx) * 4 + 3] > 128) out.push({ x: xx, y })
  return out
}

// A headline made of dust. Sweep through it and the grains scatter, then drift home.
export default function DustLetters({ text = 'kavyn', color = '#ff6a2b', density = 4, className = '' }) {
  const host = useCanvasLoop((ctx, s) => {
    let parts = []
    const step = Math.max(2, Math.round(Number(density) || 4))
    const build = () => {
      const targets = sampleText(String(text || ' '), s.w, s.h, step).slice(0, 6000)
      parts = targets.map((t) => ({ hx: t.x, hy: t.y, x: Math.random() * s.w, y: Math.random() * s.h, vx: 0, vy: 0, hot: 0 }))
    }
    build()
    document.fonts?.ready?.then(() => { try { build() } catch { /* ignore */ } }).catch(() => {})
    return {
      resize: build,
      step(dt) {
        const p = s.pointer, R = Math.max(50, s.w * 0.08)
        ctx.clearRect(0, 0, s.w, s.h)
        for (const q of parts) {
          const dx = q.x - p.x, dy = q.y - p.y, d = Math.hypot(dx, dy)
          if (d < R && d > 0.1) { const f = (1 - d / R) * 1800; q.vx += (dx / d) * f * dt; q.vy += (dy / d) * f * dt; q.hot = 1 }
          q.vx += (q.hx - q.x) * 30 * dt; q.vy += (q.hy - q.y) * 30 * dt
          q.vx *= 0.9; q.vy *= 0.9
          q.x += q.vx * dt * (s.reduce ? 4 : 1); q.y += q.vy * dt * (s.reduce ? 4 : 1)
          q.hot *= 0.96
        }
        ctx.fillStyle = '#ededef'
        for (const q of parts) if (q.hot < 0.2) ctx.fillRect(q.x, q.y, step * 0.55, step * 0.55)
        ctx.fillStyle = color
        for (const q of parts) if (q.hot >= 0.2) ctx.fillRect(q.x, q.y, step * 0.6, step * 0.6)
      },
    }
  }, [text, color, density])
  return <div ref={host} className={`relative h-full min-h-60 w-full overflow-hidden bg-bg ${className}`} role="img" aria-label={String(text)} />
}

'use client'

import { useEffect, useRef } from 'react'

// Shared 2D canvas runner for the physics and particle pieces.
// Sizes the canvas to its box (capped DPR), pauses off screen and in hidden tabs,
// tracks the pointer in CSS pixels, and hands your step() a ready context.
export function useCanvasLoop(setup, deps = []) {
  const host = useRef(null)
  useEffect(() => {
    const el = host.current
    if (!el || typeof window === 'undefined') return
    const canvas = document.createElement('canvas')
    canvas.setAttribute('aria-hidden', 'true')
    canvas.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none'
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    el.prepend(canvas)
    const reduce = !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches
    const state = { w: 0, h: 0, dpr: 1, pointer: { x: -9999, y: -9999, down: false, inside: false, vx: 0, vy: 0 }, reduce }
    const resize = () => {
      const dpr = Math.min(2, window.devicePixelRatio || 1)
      const w = Math.max(1, el.clientWidth), h = Math.max(1, el.clientHeight)
      if (w === state.w && h === state.h && dpr === state.dpr) return false
      state.w = w; state.h = h; state.dpr = dpr
      canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr)
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      return true
    }
    resize()
    let api = null
    try { api = setup(ctx, state) || {} } catch { api = {} }
    const pos = (e) => { const r = el.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top } }
    const onMove = (e) => { const p = pos(e); const q = state.pointer; q.vx = p.x - q.x; q.vy = p.y - q.y; q.x = p.x; q.y = p.y; q.inside = true; api.move?.(q) }
    const onDown = (e) => { const p = pos(e); Object.assign(state.pointer, p, { down: true, inside: true, vx: 0, vy: 0 }); try { canvas.setPointerCapture(e.pointerId) } catch { /* ignore */ } api.down?.(state.pointer) }
    const onUp = () => { state.pointer.down = false; api.up?.(state.pointer) }
    const onLeave = () => { if (!state.pointer.down) { state.pointer.inside = false; state.pointer.x = -9999; state.pointer.y = -9999 } }
    canvas.addEventListener('pointermove', onMove)
    canvas.addEventListener('pointerdown', onDown)
    canvas.addEventListener('pointerup', onUp)
    canvas.addEventListener('pointercancel', onUp)
    canvas.addEventListener('pointerleave', onLeave)
    let raf = 0, visible = true, prev = performance.now()
    const loop = (now) => {
      raf = 0
      if (resize()) api.resize?.()
      const dt = Math.min(1 / 30, Math.max(0, (now - prev) / 1000)); prev = now
      try { api.step?.(dt, now / 1000) } catch { return }
      if (visible && !document.hidden) raf = requestAnimationFrame(loop)
    }
    const start = () => { if (!raf) { prev = performance.now(); raf = requestAnimationFrame(loop) } }
    const io = typeof IntersectionObserver !== 'undefined' ? new IntersectionObserver(([e]) => { visible = !!e?.isIntersecting; if (visible) start() }) : null
    io?.observe(el)
    const onVis = () => { if (!document.hidden) start() }
    document.addEventListener('visibilitychange', onVis)
    start()
    return () => {
      cancelAnimationFrame(raf); io?.disconnect()
      document.removeEventListener('visibilitychange', onVis)
      canvas.remove()
    }
  }, deps) // eslint-disable-line react-hooks/exhaustive-deps
  return host
}

export const clamp = (v, a, b) => Math.min(b, Math.max(a, v))
